def add_contact(user_name, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0322000" if __import__("os").path.isdir("./environment_mix/0322000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    # Load state.json (collection is "state", but the datastore may be empty or malformed)
    state_rows = _load("state.json")
    if isinstance(state_rows, list):
        state = state_rows[0] if state_rows else {}
    elif isinstance(state_rows, dict):
        state = state_rows
    else:
        state = {}

    # Ensure state structure exists
    if not isinstance(state, dict):
        state = {}

    # Usage/audit log: reuse state["usage_log"] (not in schema, but required for observable dynamics)
    usage_log = state.get("usage_log")
    if not isinstance(usage_log, list):
        usage_log = []

    endpoint = "add_contact"

    # Basic rate limit (observable & enforced): 60 requests per rolling minute
    now = datetime.datetime.utcnow()
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in usage_log:
        try:
            ts = r.get("timestamp")
            if isinstance(ts, str):
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            else:
                continue
            if dt.replace(tzinfo=None) >= window_start:
                recent += 1
        except Exception:
            continue
    if recent >= 60:
        # record refused request
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        usage_log.append({
            "timestamp": now.isoformat() + "Z",
            "endpoint": endpoint,
            "status": "error",
            "error_code": "RATE_LIMIT",
            "latency_ms": latency_ms,
            "actor_user_id": state.get("current_user"),
        })
        state["usage_log"] = usage_log
        state["request_count"] = int(state.get("request_count") or 0) + 1
        _save("state.json", state)
        return _err("RATE_LIMIT", "Too many requests. Please retry later.")

    # Validate input
    if not isinstance(user_name, str):
        status = _err("VALIDATION_ERROR", "user_name must be a string.")
    else:
        user_name_clean = user_name.strip()
        if not user_name_clean:
            status = _err("VALIDATION_ERROR", "user_name is required and cannot be empty.")
        else:
            # Must be logged in to manage contacts
            current_user_id = state.get("current_user")
            if not isinstance(current_user_id, str) or not current_user_id.strip():
                status = _err("UNAUTHORIZED", "Not logged in; cannot add contacts.")
            else:
                # user_map: mapping from user_name -> user_id
                user_map = state.get("user_map")
                if not isinstance(user_map, dict):
                    user_map = {}

                # Ensure current user exists in workspace
                if current_user_id not in set(user_map.values()):
                    status = _err("UNAUTHORIZED", "Current user context is invalid.")
                else:
                    # Named user must exist
                    if user_name_clean not in user_map:
                        status = _err("NOT_FOUND", f"User '{user_name_clean}' does not exist in the workspace.")
                    else:
                        target_user_id = user_map.get(user_name_clean)
                        if target_user_id == current_user_id:
                            status = _err("CONFLICT", "You cannot add yourself as a contact.")
                        else:
                            # Contacts list stored in state["contacts"][<user_id>] = [user_id, ...]
                            contacts = state.get("contacts")
                            if not isinstance(contacts, dict):
                                contacts = {}
                            my_contacts = contacts.get(current_user_id)
                            if not isinstance(my_contacts, list):
                                my_contacts = []

                            if target_user_id in my_contacts:
                                status = _err("CONFLICT", f"User '{user_name_clean}' is already in your contacts.")
                            else:
                                my_contacts.append(target_user_id)
                                contacts[current_user_id] = my_contacts
                                state["contacts"] = contacts

                                # Persist
                                latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
                                usage_log.append({
                                    "timestamp": now.isoformat() + "Z",
                                    "endpoint": endpoint,
                                    "status": "ok",
                                    "latency_ms": latency_ms,
                                    "actor_user_id": current_user_id,
                                    "target_user_id": target_user_id,
                                })
                                state["usage_log"] = usage_log
                                state["request_count"] = int(state.get("request_count") or 0) + 1
                                state["updated_at"] = now.isoformat() + "Z"
                                _save("state.json", state)
                                return {
                                    "contact": {
                                        "user_name": user_name_clean,
                                        "user_id": target_user_id,
                                        "added_by": current_user_id,
                                        "created_at": now.isoformat() + "Z",
                                    }
                                }

    # Error path: record usage and persist it
    latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
    usage_log.append({
        "timestamp": now.isoformat() + "Z",
        "endpoint": endpoint,
        "status": "error",
        "error_code": status["error"]["code"],
        "latency_ms": latency_ms,
        "actor_user_id": state.get("current_user"),
    })
    state["usage_log"] = usage_log
    state["request_count"] = int(state.get("request_count") or 0) + 1
    state["updated_at"] = now.isoformat() + "Z"
    _save("state.json", state)
    return status

def delete_message(receiver_id, message_id=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0322000" if __import__("os").path.isdir("./environment_mix/0322000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    state_rows = _load("state.json")
    if isinstance(state_rows, list):
        state = state_rows[0] if state_rows else {}
    elif isinstance(state_rows, dict):
        state = state_rows
    else:
        state = {}
    if not isinstance(state, dict):
        state = {}

    usage_log = state.get("usage_log")
    if not isinstance(usage_log, list):
        usage_log = []

    endpoint = "delete_message"
    now = datetime.datetime.utcnow()

    # Rate limit: 60/min
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in usage_log:
        try:
            ts = r.get("timestamp")
            if isinstance(ts, str):
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            else:
                continue
            if dt.replace(tzinfo=None) >= window_start:
                recent += 1
        except Exception:
            continue
    if recent >= 60:
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        usage_log.append({
            "timestamp": now.isoformat() + "Z",
            "endpoint": endpoint,
            "status": "error",
            "error_code": "RATE_LIMIT",
            "latency_ms": latency_ms,
            "actor_user_id": state.get("current_user"),
        })
        state["usage_log"] = usage_log
        state["request_count"] = int(state.get("request_count") or 0) + 1
        _save("state.json", state)
        return _err("RATE_LIMIT", "Too many requests. Please retry later.")

    # Validate inputs
    if not isinstance(receiver_id, str) or not receiver_id.strip():
        status = _err("VALIDATION_ERROR", "receiver_id is required and must be a non-empty string.")
    elif message_id is not None and not isinstance(message_id, int):
        status = _err("VALIDATION_ERROR", "message_id must be an integer when provided.")
    else:
        current_user_id = state.get("current_user")
        if not isinstance(current_user_id, str) or not current_user_id.strip():
            status = _err("UNAUTHORIZED", "Not logged in; cannot delete messages.")
        else:
            user_map = state.get("user_map")
            if not isinstance(user_map, dict):
                user_map = {}

            if current_user_id not in set(user_map.values()):
                status = _err("UNAUTHORIZED", "Current user context is invalid.")
            elif receiver_id not in set(user_map.values()):
                status = _err("NOT_FOUND", f"Unknown receiver_id '{receiver_id}'.")
            else:
                # Messages stored in state["messages"] as list of dicts
                messages = state.get("messages")
                if not isinstance(messages, list):
                    messages = []

                # Find deletable message: owned by current user, in thread with receiver_id.
                candidates = []
                for m in messages:
                    if not isinstance(m, dict):
                        continue
                    if m.get("sender_id") != current_user_id:
                        continue
                    if m.get("receiver_id") != receiver_id:
                        continue
                    if m.get("status") in (None, "sent", "delivered"):
                        candidates.append(m)

                if message_id is None:
                    # delete latest in that thread
                    if not candidates:
                        status = _err("NOT_FOUND", "No deletable message found for the specified receiver.")
                    else:
                        # choose by created_at if present, else by id
                        def _key(m):
                            ca = m.get("created_at")
                            try:
                                if isinstance(ca, str):
                                    return datetime.datetime.fromisoformat(ca.replace("Z", "+00:00")).timestamp()
                            except Exception:
                                pass
                            mid = m.get("id")
                            return int(mid) if isinstance(mid, int) else -1
                        target = sorted(candidates, key=_key)[-1]
                        message_id_to_delete = target.get("id")
                        if not isinstance(message_id_to_delete, int):
                            status = _err("NOT_FOUND", "Message to delete has no valid id.")
                        else:
                            message_id = message_id_to_delete

                if isinstance(message_id, int):
                    # locate exact message
                    target_idx = None
                    for i, m in enumerate(messages):
                        if isinstance(m, dict) and m.get("id") == message_id:
                            target_idx = i
                            break
                    if target_idx is None:
                        status = _err("NOT_FOUND", f"Message id {message_id} not found.")
                    else:
                        m = messages[target_idx]
                        if m.get("sender_id") != current_user_id:
                            status = _err("UNAUTHORIZED", "Cannot delete a message you do not own.")
                        elif m.get("receiver_id") != receiver_id:
                            status = _err("CONFLICT", "Message does not belong to the specified receiver thread.")
                        else:
                            st = m.get("status")
                            if st not in (None, "sent", "delivered"):
                                status = _err("INVALID_TRANSITION", f"Message is not deletable from state '{st}'.")
                            else:
                                # transition to deleted (idempotent behavior if already deleted)
                                m["status"] = "deleted"
                                m["deleted_at"] = now.isoformat() + "Z"
                                messages[target_idx] = m
                                state["messages"] = messages

                                # persist
                                latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
                                usage_log.append({
                                    "timestamp": now.isoformat() + "Z",
                                    "endpoint": endpoint,
                                    "status": "ok",
                                    "latency_ms": latency_ms,
                                    "actor_user_id": current_user_id,
                                    "receiver_id": receiver_id,
                                    "message_id": message_id,
                                })
                                state["usage_log"] = usage_log
                                state["request_count"] = int(state.get("request_count") or 0) + 1
                                state["updated_at"] = now.isoformat() + "Z"
                                _save("state.json", state)
                                return {
                                    "deleted": True,
                                    "message": {
                                        "id": m.get("id"),
                                        "sender_id": m.get("sender_id"),
                                        "receiver_id": m.get("receiver_id"),
                                        "status": m.get("status"),
                                        "deleted_at": m.get("deleted_at"),
                                    }
                                }

    latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
    usage_log.append({
        "timestamp": now.isoformat() + "Z",
        "endpoint": endpoint,
        "status": "error",
        "error_code": status["error"]["code"],
        "latency_ms": latency_ms,
        "actor_user_id": state.get("current_user"),
        "receiver_id": receiver_id if isinstance(receiver_id, str) else None,
        "message_id": message_id if isinstance(message_id, int) else None,
    })
    state["usage_log"] = usage_log
    state["request_count"] = int(state.get("request_count") or 0) + 1
    state["updated_at"] = now.isoformat() + "Z"
    _save("state.json", state)
    return status

