    if isinstance(state_rows, list):
        state = state_rows[0] if state_rows else {}
    elif isinstance(state_rows, dict):
        state = state_rows
    else:
        state = {}
    if not isinstance(state, dict):
        state = {}

    usage_log = state.get("usage_log")
    if not isinstance(usage_log, list):
        usage_log = []

    endpoint = "search_messages"
    now = datetime.datetime.utcnow()

    # Rate limit: 60/min
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in usage_log:
        try:
            ts = r.get("timestamp")
            if isinstance(ts, str):
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            else:
                continue
            if dt.replace(tzinfo=None) >= window_start:
                recent += 1
        except Exception:
            continue
    if recent >= 60:
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        usage_log.append({
            "timestamp": now.isoformat() + "Z",
            "endpoint": endpoint,
            "status": "error",
            "error_code": "RATE_LIMIT",
            "latency_ms": latency_ms,
            "actor_user_id": state.get("current_user"),
        })
        state["usage_log"] = usage_log
        state["request_count"] = int(state.get("request_count") or 0) + 1
        _save("state.json", state)
        return _err("RATE_LIMIT", "Too many requests. Please retry later.")

    # Validate keyword
    if not isinstance(keyword, str):
        status = _err("VALIDATION_ERROR", "keyword must be a string.")
    else:
        kw = keyword.strip()
        if not kw:
            status = _err("VALIDATION_ERROR", "keyword is required and cannot be empty.")
        else:
            current_user_id = state.get("current_user")
            user_map = state.get("user_map")
            if not isinstance(user_map, dict):
                user_map = {}
            if not isinstance(current_user_id, str) or not current_user_id.strip():
                status = _err("UNAUTHORIZED", "Not logged in; cannot search messages.")
            elif current_user_id not in set(user_map.values()):
                status = _err("UNAUTHORIZED", "Workspace session is invalid or expired.")
            else:
                messages = state.get("messages")
                if not isinstance(messages, list):
                    messages = []
                inbox = state.get("inbox")
                if not isinstance(inbox, list):
                    inbox = []

                # Search across structured messages and legacy inbox entries
                kw_l = kw.lower()
                results = []

                for m in messages:
                    if not isinstance(m, dict):
                        continue
                    # Only messages where user is sender or receiver; exclude deleted for that user where possible
                    if m.get("sender_id") != current_user_id and m.get("receiver_id") != current_user_id:
                        continue
                    body = m.get("body")
                    if isinstance(body, str) and kw_l in body.lower():
                        results.append({
                            "id": m.get("id"),
                            "sender_id": m.get("sender_id"),
                            "receiver_id": m.get("receiver_id"),
                            "body": body,
                            "status": m.get("status", "sent"),
                            "created_at": m.get("created_at"),
                        })

                for entry in inbox:
                    if not isinstance(entry, dict):
                        continue
                    items = list(entry.items())
                    if not items:
                        continue
                    rid, content = items[0]
                    if not isinstance(content, str):
                        continue
                    if kw_l in content.lower():
                        results.append({
                            "id": None,
                            "sender_id": current_user_id,
                            "receiver_id": rid,
                            "body": content,
                            "status": "legacy",
                            "created_at": None,
