def send_message(receiver_id, message, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0322000" if __import__("os").path.isdir("./environment_mix/0322000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    state_rows = _load("state.json")
    if isinstance(state_rows, list):
        state = state_rows[0] if state_rows else {}
    elif isinstance(state_rows, dict):
        state = state_rows
    else:
        state = {}
    if not isinstance(state, dict):
        state = {}

    usage_log = state.get("usage_log")
    if not isinstance(usage_log, list):
        usage_log = []

    endpoint = "send_message"
    now = datetime.datetime.utcnow()

    # Rate limit: 60/min
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in usage_log:
        try:
            ts = r.get("timestamp")
            if isinstance(ts, str):
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            else:
                continue
            if dt.replace(tzinfo=None) >= window_start:
                recent += 1
        except Exception:
            continue
    if recent >= 60:
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        usage_log.append({
            "timestamp": now.isoformat() + "Z",
            "endpoint": endpoint,
            "status": "error",
            "error_code": "RATE_LIMIT",
            "latency_ms": latency_ms,
            "actor_user_id": state.get("current_user"),
        })
        state["usage_log"] = usage_log
        state["request_count"] = int(state.get("request_count") or 0) + 1
        _save("state.json", state)
        return _err("RATE_LIMIT", "Too many requests. Please retry later.")

    # Validate inputs
    if not isinstance(receiver_id, str) or not receiver_id.strip():
        status = _err("VALIDATION_ERROR", "receiver_id is required and must be a non-empty string.")
    elif not isinstance(message, str):
        status = _err("VALIDATION_ERROR", "message must be a string.")
    else:
        body = message.strip()
        if not body:
            status = _err("VALIDATION_ERROR", "message is required and cannot be empty.")
        else:
            current_user_id = state.get("current_user")
            if not isinstance(current_user_id, str) or not current_user_id.strip():
                status = _err("UNAUTHORIZED", "Not logged in; cannot send messages.")
            else:
                user_map = state.get("user_map")
                if not isinstance(user_map, dict):
                    user_map = {}

                if current_user_id not in set(user_map.values()):
                    status = _err("UNAUTHORIZED", "Current user context is invalid.")
                elif receiver_id not in set(user_map.values()):
                    status = _err("NOT_FOUND", f"Receiver '{receiver_id}' does not exist in the workspace.")
                elif receiver_id == current_user_id:
                    status = _err("CONFLICT", "Cannot send a message to yourself.")
                else:
                    # Optional permission rule: require receiver to be in contacts if contacts exist
                    contacts = state.get("contacts")
                    if isinstance(contacts, dict) and contacts.get(current_user_id) is not None:
                        my_contacts = contacts.get(current_user_id)
                        if isinstance(my_contacts, list) and receiver_id not in my_contacts:
                            status = _err("UNAUTHORIZED", "You are not permitted to message this receiver (not a contact).")
                        else:
                            status = None
                    else:
                        status = None

                    if status is None:
                        # Create message id using monotonic counter
                        msg_counter = state.get("message_count")
                        if not isinstance(msg_counter, int) or msg_counter < 0:
                            msg_counter = 0
                        msg_counter += 1
                        state["message_count"] = msg_counter

                        # Also keep generated_ids in state (schema field)
                        generated_ids = state.get("generated_ids")
                        if not isinstance(generated_ids, list):
                            generated_ids = []
                        generated_ids.append(msg_counter)
                        state["generated_ids"] = generated_ids

                        msg = {
                            "id": msg_counter,
                            "sender_id": current_user_id,
                            "receiver_id": receiver_id,
                            "body": body,
                            "status": "sent",
                            "created_at": now.isoformat() + "Z",
                        }
                        messages = state.get("messages")
                        if not isinstance(messages, list):
                            messages = []
                        messages.append(msg)
                        state["messages"] = messages

                        # Legacy inbox compatibility: append {receiver_id: message} so older search works too
                        inbox = state.get("inbox")
                        if not isinstance(inbox, list):
                            inbox = []
                        inbox.append({receiver_id: body})
                        state["inbox"] = inbox

                        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
                        usage_log.append({
                            "timestamp": now.isoformat() + "Z",
                            "endpoint": endpoint,
                            "status": "ok",
                            "latency_ms": latency_ms,
                            "actor_user_id": current_user_id,
                            "receiver_id": receiver_id,
                            "message_id": msg_counter,
                        })
                        state["usage_log"] = usage_log
                        state["request_count"] = int(state.get("request_count") or 0) + 1
                        state["updated_at"] = now.isoformat() + "Z"
                        _save("state.json", state)

                        return {"message": msg}

    latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
    usage_log.append({
        "timestamp": now.isoformat() + "Z",
        "endpoint": endpoint,
        "status": "error",
        "error_code": status["error"]["code"],
        "latency_ms": latency_ms,
        "actor_user_id": state.get("current_user"),
        "receiver_id": receiver_id if isinstance(receiver_id, str) else None,
    })
    state["usage_log"] = usage_log
    state["request_count"] = int(state.get("request_count") or 0) + 1
    state["updated_at"] = now.isoformat() + "Z"
    _save("state.json", state)
    return status

_DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0322000" if __import__("os").path.isdir("./environment_mix/0322000") else "/app/database")
def view_messages_sent():
    import json, os, math, random
    _S = json.load(open(os.path.join(_DB, 'state.json'), encoding='utf-8'))
    if not _S.get("current_user"):
        return {"error": "No user is currently logged in."}
    sent = {}
    for msg in _S.get("inbox", []):
        items = list(msg.items())
        if not items:
            continue
        receiver, content = items[0]
        sent.setdefault(receiver, []).append(content)
    return {"messages": sent}
